CREATE OR REPLACE FUNCTION fn_actualizar_umbral_configuracion(
    p_id_configuracion BIGINT,
    p_umbral_minimo NUMERIC,
    p_umbral_maximo NUMERIC
)
RETURNS VOID AS $$
BEGIN
    IF p_umbral_minimo >= p_umbral_maximo THEN
        RAISE EXCEPTION 'umbral_minimo (%) debe ser menor que umbral_maximo (%)',
            p_umbral_minimo, p_umbral_maximo;
    END IF;

    UPDATE configuracion_variable
       SET umbral_minimo = p_umbral_minimo,
           umbral_maximo = p_umbral_maximo,
           fecha_actualizacion = now()
     WHERE id_configuracion = p_id_configuracion;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'configuracion_variable % no existe', p_id_configuracion;
    END IF;

    -- COMMIT implícito si todo fue exitoso.
EXCEPTION
    WHEN OTHERS THEN
        -- ROLLBACK automático de todos los cambios de esta función.
        RAISE;
END;
$$ LANGUAGE plpgsql;
